<script setup lang="ts">
import { PhAirplaneTilt,PhMagnifyingGlass,PhArrowRight } from '@phosphor-icons/vue'
import { flightRecords,flightTotals,formatNumber,formatMinutes,formatDate,type FlightRecord } from '../data/operations'
import type { RecordDetails } from '../types/workspace'
const emit=defineEmits<{inspect:[detail:RecordDetails]}>()
const query=ref(''),period=ref('all')
const periods=[...new Set(flightRecords.map(f=>f.date.slice(0,7)))].sort().reverse()
const filtered=computed(()=>flightRecords.filter(f=>(period.value==='all'||f.date.startsWith(period.value))&&`${f.id} ${f.from} ${f.to} ${f.crew}`.toLocaleLowerCase('id').includes(query.value.trim().toLocaleLowerCase('id'))).sort((a,b)=>b.date.localeCompare(a.date)||b.departure.localeCompare(a.departure)))
const filteredKm=computed(()=>filtered.value.reduce((total,f)=>total+f.distanceKm,0))
function inspect(flight:FlightRecord){emit('inspect',{eyebrow:`FLIGHT LOG / ${flight.id}`,title:`${flight.from} → ${flight.to}`,description:flight.note,fields:[{label:'Tanggal',value:formatDate(flight.date)},{label:'Berangkat',value:`${flight.departure} WIT`},{label:'Tiba',value:`${flight.arrival} WIT`},{label:'Durasi tercatat',value:formatMinutes(flight.minutes)},{label:'Jarak contoh',value:`${formatNumber(flight.distanceKm)} km`},{label:'Siklus',value:'1 takeoff / landing'},{label:'Awak',value:flight.crew}],note:'Semua catatan bersifat sintetis. Jarak tidak dihitung dari GPS dan bukan total utilisasi aktual pesawat AMA.'})}
</script>
<template>
 <section class="operations-page flights-page" aria-labelledby="flights-title">
  <header class="operations-heading"><div><span class="operations-eyebrow">C208 / FLIGHT LOG</span><h2 id="flights-title">Riwayat penerbangan</h2><p>Catatan perjalanan, durasi, dan jarak yang terakumulasi pada pesawat demo.</p></div><span class="data-origin">Data contoh</span></header>
  <p class="operations-data-note"><PhAirplaneTilt :size="18" /> Rute, waktu, dan jarak adalah data demonstrasi; belum tersambung ke flight log atau pelacakan pesawat.</p>
  <div class="operations-metrics flight-metrics"><div><span>Jarak tercatat</span><strong>{{ formatNumber(flightTotals.distanceKm) }} <em>km</em></strong><small>Akumulasi seluruh catatan contoh</small></div><div><span>Durasi terbang</span><strong>{{ formatMinutes(flightTotals.minutes) }}</strong><small>Jumlah durasi pada log</small></div><div><span>Siklus tercatat</span><strong>{{ flightTotals.cycles }}</strong><small>Satu siklus per penerbangan</small></div><div><span>Penerbangan terakhir</span><strong class="metric-date">{{ formatDate(flightRecords.at(-1)!.date) }}</strong><small>{{ flightRecords.at(-1)!.from }} → {{ flightRecords.at(-1)!.to }}</small></div></div>
  <div class="operations-section-heading"><div><h3>Catatan perjalanan</h3><p>Waktu menggunakan WIT. Detail menyertakan awak dan catatan perjalanan.</p></div><span>{{ filtered.length }} penerbangan · {{ formatNumber(filteredKm) }} km</span></div>
  <div class="operations-filters"><label class="operations-search"><span class="sr-only">Cari penerbangan</span><PhMagnifyingGlass :size="18" /><input v-model="query" aria-label="Cari penerbangan" placeholder="Cari nomor penerbangan, rute, atau awak…" /></label><label class="operations-select"><span>Periode</span><select v-model="period" aria-label="Filter periode penerbangan"><option value="all">Semua periode</option><option v-for="month in periods" :key="month" :value="month">{{ new Date(`${month}-01T00:00:00+09:00`).toLocaleDateString('id-ID',{month:'long',year:'numeric',timeZone:'Asia/Jayapura'}) }}</option></select></label></div>
  <div v-if="!filtered.length" class="operations-empty"><PhAirplaneTilt :size="32" /><h3>Penerbangan tidak ditemukan</h3><p>Ubah rute, awak, atau periode pencarian.</p><button class="button" @click="query='';period='all'">Hapus filter</button></div>
  <div v-else class="operations-table-wrap" tabindex="0" aria-label="Daftar penerbangan, geser bila diperlukan"><table class="operations-table flight-table"><caption class="sr-only">Riwayat penerbangan contoh C208 Demo</caption><thead><tr><th>Tanggal / nomor</th><th>Rute</th><th>Berangkat / tiba</th><th>Durasi</th><th>Jarak</th><th><span class="sr-only">Detail penerbangan</span></th></tr></thead><tbody><tr v-for="flight in filtered" :key="flight.id" :data-flight-id="flight.id"><td><strong>{{ formatDate(flight.date) }}</strong><small class="record-code">{{ flight.id }}</small></td><td><span class="flight-route">{{ flight.from }}<PhArrowRight :size="16" />{{ flight.to }}</span><small>{{ flight.crew }}</small></td><td>{{ flight.departure }} – {{ flight.arrival }}<small>WIT</small></td><td>{{ formatMinutes(flight.minutes) }}</td><td class="numeric">{{ formatNumber(flight.distanceKm) }} km</td><td><button class="button subtle" :aria-label="`Detail penerbangan ${flight.id}`" @click="inspect(flight)">Detail<PhArrowRight :size="15" /></button></td></tr></tbody></table></div>
 </section>
</template>
